"""AST node types used by the minisql parser and evaluator."""

from dataclasses import dataclass, field
from typing import Any, List, Optional, Tuple


@dataclass
class Literal:
    value: Any


@dataclass
class Column:
    name: str
    index: Optional[int] = field(default=None, compare=False)


@dataclass
class Unary:
    op: str
    operand: "Expr"


@dataclass
class Binary:
    op: str
    left: "Expr"
    right: "Expr"


@dataclass
class IsNull:
    operand: "Expr"
    negated: bool


@dataclass
class InList:
    operand: "Expr"
    items: Tuple["Expr", ...]
    negated: bool


@dataclass
class Between:
    operand: "Expr"
    low: "Expr"
    high: "Expr"
    negated: bool


@dataclass
class Like:
    operand: "Expr"
    pattern: "Expr"
    negated: bool


@dataclass
class FuncCall:
    # Function names are stored upper-cased so that comparisons are
    # case-insensitive.
    name: str
    args: Tuple["Expr", ...] = ()
    star: bool = False


Expr = Any


@dataclass
class SelectItem:
    expr: Expr
    alias: Optional[str]
    text: str


@dataclass
class OrderItem:
    expr: Expr
    descending: bool = False


@dataclass
class Query:
    distinct: bool
    select_star: bool
    select_items: List[SelectItem]
    table_name: str
    where: Optional[Expr] = None
    group_by: List[Expr] = field(default_factory=list)
    having: Optional[Expr] = None
    order_by: List[OrderItem] = field(default_factory=list)
    limit: Optional[int] = None
    offset: int = 0

