"""Recursive-descent parser for the minisql query language."""

from ._ast import (
    Between,
    Binary,
    Column,
    FuncCall,
    InList,
    IsNull,
    Like,
    Literal,
    OrderItem,
    Query,
    SelectItem,
    Unary,
)
from ._errors import QueryError
from ._lexer import tokenize

_COMPARISON_OPS = {"=", "!=", "<>", "<", "<=", ">", ">="}


class _Parser:
    def __init__(self, sql):
        self.sql = sql
        self.tokens = tokenize(sql)
        self.pos = 0

    # -- token helpers ---------------------------------------------------

    def peek(self, offset=0):
        index = self.pos + offset
        if index >= len(self.tokens):
            index = len(self.tokens) - 1
        return self.tokens[index]

    def advance(self):
        token = self.tokens[self.pos]
        if token.kind != "EOF":
            self.pos += 1
        return token

    def check(self, kind):
        return self.peek().kind == kind

    def match(self, kind):
        if self.check(kind):
            return self.advance()
        return None

    def expect(self, kind, what=None):
        if not self.check(kind):
            self.error("expected %s" % (what or repr(kind)))
        return self.advance()

    def error(self, message, token=None):
        if token is None:
            token = self.peek()
        raise QueryError("%s at position %d" % (message, token.start + 1))

    def parse_name(self, what="name"):
        token = self.peek()
        if token.kind not in ("IDENT", "QIDENT"):
            self.error("expected %s" % what)
        self.advance()
        return token.value

    # -- expressions -----------------------------------------------------

    def parse_expr(self):
        return self.parse_or()

    def parse_or(self):
        expr = self.parse_and()
        while self.match("OR"):
            right = self.parse_and()
            expr = Binary("OR", expr, right)
        return expr

    def parse_and(self):
        expr = self.parse_not()
        while self.match("AND"):
            right = self.parse_not()
            expr = Binary("AND", expr, right)
        return expr

    def parse_not(self):
        if self.match("NOT"):
            return Unary("NOT", self.parse_not())
        return self.parse_comparison()

    def parse_comparison(self):
        left = self.parse_additive()

        token = self.peek()
        if token.kind in _COMPARISON_OPS:
            self.advance()
            right = self.parse_additive()
            return Binary(token.kind, left, right)

        if self.match("IS"):
            negated = bool(self.match("NOT"))
            self.expect("NULL", "NULL")
            return IsNull(left, negated)

        negated = False
        if self.check("NOT") and self.peek(1).kind in ("IN", "BETWEEN", "LIKE"):
            self.advance()
            negated = True

        if self.match("IN"):
            self.expect("(", "'('")
            items = [self.parse_expr()]
            while self.match(","):
                items.append(self.parse_expr())
            self.expect(")", "')'")
            return InList(left, tuple(items), negated)

        if self.match("BETWEEN"):
            low = self.parse_additive()
            self.expect("AND", "AND")
            high = self.parse_additive()
            return Between(left, low, high, negated)

        if self.match("LIKE"):
            pattern = self.parse_additive()
            return Like(left, pattern, negated)

        if negated:
            # We consumed NOT, but it was not followed by IN/BETWEEN/LIKE.
            # This should be impossible because we only consume it after
            # checking the following token.
            self.error("unexpected NOT")

        return left

    def parse_additive(self):
        expr = self.parse_multiplicative()
        while self.peek().kind in ("+", "-", "||"):
            op = self.advance().kind
            right = self.parse_multiplicative()
            expr = Binary(op, expr, right)
        return expr

    def parse_multiplicative(self):
        expr = self.parse_unary()
        while self.peek().kind in ("*", "/"):
            op = self.advance().kind
            right = self.parse_unary()
            expr = Binary(op, expr, right)
        return expr

    def parse_unary(self):
        if self.match("-"):
            return Unary("-", self.parse_unary())
        return self.parse_atom()

    def parse_atom(self):
        token = self.peek()

        if self.match("("):
            expr = self.parse_expr()
            self.expect(")", "')'")
            return expr

        if token.kind == "NUMBER":
            self.advance()
            raw = token.value
            if "." in raw:
                return Literal(float(raw))
            return Literal(int(raw))

        if token.kind == "STRING":
            self.advance()
            return Literal(token.value)

        if token.kind == "NULL":
            self.advance()
            return Literal(None)

        if token.kind == "TRUE":
            self.advance()
            return Literal(True)

        if token.kind == "FALSE":
            self.advance()
            return Literal(False)

        if token.kind in ("IDENT", "QIDENT"):
            self.advance()
            name = token.value
            if self.match("("):
                star = False
                args = []
                if self.match("*"):
                    star = True
                    self.expect(")", "')'")
                elif not self.match(")"):
                    args.append(self.parse_expr())
                    while self.match(","):
                        args.append(self.parse_expr())
                    self.expect(")", "')'")
                return FuncCall(name.upper(), tuple(args), star)
            return Column(name)

        self.error("expected an expression")

    # -- statements ------------------------------------------------------

    def parse_select_item(self):
        start = self.peek().start
        expr = self.parse_expr()
        end = self.tokens[self.pos - 1].end
        text = self.sql[start:end]

        alias = None
        if self.match("AS"):
            alias = self.parse_name("an alias")
        elif self.peek().kind in ("IDENT", "QIDENT"):
            alias = self.parse_name("an alias")

        return SelectItem(expr, alias, text)

    def parse_order_item(self):
        expr = self.parse_expr()
        descending = False
        if self.match("DESC"):
            descending = True
        else:
            self.match("ASC")
        return OrderItem(expr, descending)

    def parse_limit_value(self, what):
        token = self.expect("NUMBER", "a non-negative integer")
        raw = token.value
        if "." in raw:
            self.error("%s must be a non-negative integer" % what, token)
        return int(raw)

    def parse(self):
        self.expect("SELECT", "SELECT")
        distinct = bool(self.match("DISTINCT"))

        select_star = False
        select_items = []
        if self.match("*"):
            select_star = True
        else:
            select_items.append(self.parse_select_item())
            while self.match(","):
                select_items.append(self.parse_select_item())

        self.expect("FROM", "FROM")
        table_name = self.parse_name("a table name")

        where = None
        if self.match("WHERE"):
            where = self.parse_expr()

        group_by = []
        if self.match("GROUP"):
            self.expect("BY", "BY")
            group_by.append(self.parse_expr())
            while self.match(","):
                group_by.append(self.parse_expr())

        having = None
        if self.match("HAVING"):
            having = self.parse_expr()

        order_by = []
        if self.match("ORDER"):
            self.expect("BY", "BY")
            order_by.append(self.parse_order_item())
            while self.match(","):
                order_by.append(self.parse_order_item())

        limit = None
        offset = 0
        if self.match("LIMIT"):
            limit = self.parse_limit_value("LIMIT")
            if self.match("OFFSET"):
                offset = self.parse_limit_value("OFFSET")

        self.match(";")
        self.expect("EOF", "end of query")

        return Query(
            distinct=distinct,
            select_star=select_star,
            select_items=select_items,
            table_name=table_name,
            where=where,
            group_by=group_by,
            having=having,
            order_by=order_by,
            limit=limit,
            offset=offset,
        )


def parse(sql):
    """Parse ``sql`` into a :class:`Query`."""
    return _Parser(sql).parse()

