import csv
import decimal
import os
import re
from dataclasses import dataclass, field
from decimal import Decimal, ROUND_HALF_UP
from functools import cmp_to_key, lru_cache
from typing import Any, List, Optional, Tuple

from ._ast import (
    Between,
    Binary,
    Column,
    FuncCall,
    InList,
    IsNull,
    Like,
    Literal,
    Query,
    SelectItem,
    Unary,
)
from ._errors import QueryError
from ._parser import parse

_AGGREGATES = {"COUNT", "SUM", "AVG", "MIN", "MAX"}

_INT_RE = re.compile(r"-?[0-9]+\Z")
_DECIMAL_RE = re.compile(r"-?(?:[0-9]+\.[0-9]*|[0-9]*\.[0-9]+)\Z")


# ---------------------------------------------------------------------------
# Tables and CSV loading


@dataclass
class _Table:
    columns: List[str]
    rows: List[Tuple[Any, ...]]
    _index: dict = field(default_factory=dict, init=False, repr=False)

    def __post_init__(self):
        index = {}
        for i, name in enumerate(self.columns):
            index.setdefault(name.casefold(), i)
        self._index = index

    def column_index(self, name):
        try:
            return self._index[name.casefold()]
        except KeyError:
            raise QueryError("unknown column: %s" % name)

    def column_value(self, row, index):
        return row[index]


def _convert_field(field):
    if field == "":
        return None
    if _INT_RE.fullmatch(field):
        return int(field)
    if _DECIMAL_RE.fullmatch(field):
        return float(field)
    return field


def _load_table(name, directory):
    path = os.path.join(os.fspath(directory), name + ".csv")
    try:
        handle = open(path, "r", newline="", encoding="utf-8")
    except FileNotFoundError:
        raise QueryError("unknown table: %s" % name)
    except OSError as exc:
        raise QueryError("cannot read table %s: %s" % (name, exc))

    try:
        with handle:
            reader = csv.reader(handle)
            try:
                header = next(reader)
            except StopIteration:
                raise QueryError("table %s has no header" % name)

            if not header:
                raise QueryError("table %s has no header" % name)

            rows = []
            for line_number, raw_row in enumerate(reader, 2):
                if not raw_row:
                    continue
                if len(raw_row) != len(header):
                    raise QueryError(
                        "table %s line %d has %d fields, expected %d"
                        % (name, line_number, len(raw_row), len(header))
                    )
                rows.append(tuple(_convert_field(value) for value in raw_row))
    except csv.Error as exc:
        raise QueryError("cannot read table %s: %s" % (name, exc))
    except UnicodeError as exc:
        raise QueryError("cannot read table %s: %s" % (name, exc))
    except OSError as exc:
        raise QueryError("cannot read table %s: %s" % (name, exc))

    return _Table(list(header), rows)


# ---------------------------------------------------------------------------
# Expression validation


def _children(expr):
    if isinstance(expr, Unary):
        yield expr.operand
    elif isinstance(expr, Binary):
        yield expr.left
        yield expr.right
    elif isinstance(expr, IsNull):
        yield expr.operand
    elif isinstance(expr, InList):
        yield expr.operand
        for item in expr.items:
            yield item
    elif isinstance(expr, Between):
        yield expr.operand
        yield expr.low
        yield expr.high
    elif isinstance(expr, Like):
        yield expr.operand
        yield expr.pattern
    elif isinstance(expr, FuncCall):
        for arg in expr.args:
            yield arg


def _contains_aggregate(expr):
    if isinstance(expr, FuncCall):
        if expr.name in _AGGREGATES:
            return True
        return any(_contains_aggregate(arg) for arg in expr.args)
    return any(_contains_aggregate(child) for child in _children(expr))


def _validate_expr(expr, table, in_where=False, inside_aggregate=False):
    if isinstance(expr, Literal):
        return

    if isinstance(expr, Column):
        index = table.column_index(expr.name)
        # Canonicalize to the header's spelling so that structural
        # comparisons (GROUP BY matching) are case-insensitive.
        expr.name = table.columns[index]
        expr.index = index
        return

    if isinstance(expr, FuncCall):
        name = expr.name
        if name in _AGGREGATES:
            if in_where:
                raise QueryError("aggregates are not allowed in WHERE")
            if inside_aggregate:
                raise QueryError("aggregates cannot be nested")

            if name == "COUNT" and expr.star:
                if expr.args:
                    raise QueryError("COUNT(*) takes no other arguments")
            else:
                if expr.star or len(expr.args) != 1:
                    raise QueryError(
                        "wrong number of arguments to %s" % name
                    )
                _validate_expr(
                    expr.args[0], table, in_where, inside_aggregate=True
                )
            return

        if expr.star:
            raise QueryError("wrong number of arguments to %s" % name)
        _validate_scalar(name, expr.args)
        for arg in expr.args:
            _validate_expr(arg, table, in_where, inside_aggregate)
        return

    for child in _children(expr):
        _validate_expr(child, table, in_where, inside_aggregate)


def _validate_scalar(name, args):
    count = len(args)
    if name in ("LOWER", "UPPER", "LENGTH", "ABS"):
        if count != 1:
            raise QueryError("wrong number of arguments to %s" % name)
    elif name == "ROUND":
        if count not in (1, 2):
            raise QueryError("wrong number of arguments to ROUND")
    elif name == "COALESCE":
        if count < 1:
            raise QueryError("wrong number of arguments to COALESCE")
    else:
        raise QueryError("unknown function: %s" % name)


def _group_safe(expr, group_by):
    for group_expr in group_by:
        if expr == group_expr:
            return True

    if isinstance(expr, Literal):
        return True
    if isinstance(expr, FuncCall) and expr.name in _AGGREGATES:
        return True
    if isinstance(expr, Column):
        return False

    return all(_group_safe(child, group_by) for child in _children(expr))


def _find_output_column(columns, name):
    folded = name.casefold()
    for i, column in enumerate(columns):
        if column.casefold() == folded:
            return i
    return None


@dataclass
class _Prepared:
    items: List[SelectItem]
    columns: List[str]
    grouped: bool
    # Each entry is ("output", index, descending) or ("expr", expr, descending).
    order: List[Tuple[str, Any, bool]]


def _prepare(query, table):
    if query.select_star:
        items = [
            SelectItem(Column(name, i), None, name)
            for i, name in enumerate(table.columns)
        ]
    else:
        items = query.select_items

    for item in items:
        _validate_expr(item.expr, table)

    if query.where is not None:
        _validate_expr(query.where, table, in_where=True)

    for expr in query.group_by:
        _validate_expr(expr, table)
        if _contains_aggregate(expr):
            raise QueryError("aggregates are not allowed in GROUP BY")

    if query.having is not None:
        _validate_expr(query.having, table)

    columns = []
    for item in items:
        if item.alias is not None:
            columns.append(item.alias)
        elif isinstance(item.expr, Column):
            columns.append(table.columns[item.expr.index])
        else:
            columns.append(item.text)

    order = []
    for order_item in query.order_by:
        expr = order_item.expr
        if (
            isinstance(expr, Literal)
            and isinstance(expr.value, int)
            and not isinstance(expr.value, bool)
        ):
            number = expr.value
            if number < 1 or number > len(columns):
                raise QueryError(
                    "ORDER BY position %d is out of range" % number
                )
            order.append(("output", number - 1, order_item.descending))
            continue

        if isinstance(expr, Column):
            output_index = _find_output_column(columns, expr.name)
            if output_index is not None:
                order.append(
                    ("output", output_index, order_item.descending)
                )
                continue

        _validate_expr(expr, table)
        order.append(("expr", expr, order_item.descending))

    grouped = bool(query.group_by)
    if not grouped:
        grouped = any(_contains_aggregate(item.expr) for item in items)
    if not grouped and query.having is not None:
        grouped = _contains_aggregate(query.having)
    if not grouped:
        grouped = any(
            kind == "expr" and _contains_aggregate(expr)
            for kind, expr, _ in order
        )

    if grouped:
        for item in items:
            if not _group_safe(item.expr, query.group_by):
                raise QueryError(
                    "column is not in GROUP BY and is not aggregated"
                )
        if query.having is not None and not _group_safe(
            query.having, query.group_by
        ):
            raise QueryError(
                "column is not in GROUP BY and is not aggregated"
            )
        for kind, expr, _ in order:
            if kind == "expr" and not _group_safe(expr, query.group_by):
                raise QueryError(
                    "column is not in GROUP BY and is not aggregated"
                )

    return _Prepared(items, columns, grouped, order)


# ---------------------------------------------------------------------------
# Evaluation contexts


class _RowContext:
    __slots__ = ("table", "row")

    def __init__(self, table, row):
        self.table = table
        self.row = row

    def column(self, index):
        return self.row[index]


@dataclass
class _GroupContext:
    table: _Table
    rows: List[Tuple[Any, ...]]
    representative: Optional[Tuple[Any, ...]]

    def column(self, index):
        if self.representative is None:
            raise QueryError(
                "column is not in GROUP BY and the group has no rows"
            )
        return self.representative[index]


# ---------------------------------------------------------------------------
# Value semantics


def _is_number(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _type_name(value):
    if value is None:
        return "NULL"
    if isinstance(value, bool):
        return "boolean"
    if _is_number(value):
        return "number"
    if isinstance(value, str):
        return "string"
    return type(value).__name__


def _value_key(value):
    if value is None:
        return ("null",)
    if isinstance(value, bool):
        return ("bool", value)
    if _is_number(value):
        return ("number", value)
    if isinstance(value, str):
        return ("string", value)
    return ("other", repr(value))


def _compare_values(left, right):
    """Compare two non-NULL values using SQL comparison rules."""
    if _is_number(left) and _is_number(right):
        if left < right:
            return -1
        if left > right:
            return 1
        return 0

    if isinstance(left, str) and isinstance(right, str):
        if left < right:
            return -1
        if left > right:
            return 1
        return 0

    if isinstance(left, bool) and isinstance(right, bool):
        if left < right:
            return -1
        if left > right:
            return 1
        return 0

    raise QueryError(
        "cannot compare %s with %s" % (_type_name(left), _type_name(right))
    )


def _compare_op(left, right, op):
    if left is None or right is None:
        return None
    comparison = _compare_values(left, right)
    if op == "=":
        return comparison == 0
    if op in ("!=", "<>"):
        return comparison != 0
    if op == "<":
        return comparison < 0
    if op == "<=":
        return comparison <= 0
    if op == ">":
        return comparison > 0
    if op == ">=":
        return comparison >= 0
    raise QueryError("unknown comparison operator: %s" % op)


def _check_bool(value, what):
    if value is None or isinstance(value, bool):
        return value
    raise QueryError("%s must be a boolean" % what)


def _logical_and(left, right):
    left = _check_bool(left, "AND")
    right = _check_bool(right, "AND")
    if left is False or right is False:
        return False
    if left is None or right is None:
        return None
    return True


def _logical_or(left, right):
    left = _check_bool(left, "OR")
    right = _check_bool(right, "OR")
    if left is True or right is True:
        return True
    if left is None or right is None:
        return None
    return False


def _negate(value):
    if value is None:
        return None
    if isinstance(value, bool):
        return not value
    raise QueryError("NOT must be applied to a boolean")


def _condition_is_true(value, what):
    if value is True:
        return True
    if value is False or value is None:
        return False
    raise QueryError("%s must be a boolean" % what)


@lru_cache(maxsize=256)
def _like_regex(pattern):
    parts = [r"\A"]
    for char in pattern:
        if char == "%":
            parts.append(".*")
        elif char == "_":
            parts.append(".")
        else:
            parts.append(re.escape(char))
    parts.append(r"\Z")
    return re.compile("".join(parts), re.DOTALL)


def _to_text(value):
    return str(value)


def _round_value(value, digits):
    if digits is None:
        target = Decimal(1)
    else:
        target = Decimal(1).scaleb(-digits)

    decimal_value = Decimal(str(value))
    try:
        with decimal.localcontext() as context:
            context.prec = max(
                34,
                abs(decimal_value.adjusted()) + abs(digits or 0) + 10,
            )
            result = decimal_value.quantize(target, rounding=ROUND_HALF_UP)
    except (decimal.InvalidOperation, ValueError):
        raise QueryError("cannot round value")

    if digits is None:
        return int(result)
    return float(result)


# ---------------------------------------------------------------------------
# Expression evaluation


def _eval_scalar(call, context):
    name = call.name
    args = call.args

    if name == "COALESCE":
        for arg in args:
            value = _eval(arg, context)
            if value is not None:
                return value
        return None

    values = [_eval(arg, context) for arg in args]

    if name in ("LOWER", "UPPER", "LENGTH"):
        value = values[0]
        if value is None:
            return None
        if not isinstance(value, str):
            raise QueryError("%s expects a string" % name)
        if name == "LOWER":
            return value.lower()
        if name == "UPPER":
            return value.upper()
        return len(value)

    if name == "ABS":
        value = values[0]
        if value is None:
            return None
        if not _is_number(value):
            raise QueryError("ABS expects a number")
        return abs(value)

    if name == "ROUND":
        value = values[0]
        digits = values[1] if len(values) == 2 else None
        if value is None or digits is None and len(values) == 2:
            return None
        if not _is_number(value):
            raise QueryError("ROUND expects a number")
        if len(values) == 2:
            if not isinstance(digits, int) or isinstance(digits, bool):
                raise QueryError("ROUND's second argument must be an integer")
        return _round_value(value, digits)

    raise QueryError("unknown function: %s" % name)


def _eval_aggregate(call, context):
    if not isinstance(context, _GroupContext):
        raise QueryError("aggregate used outside an aggregate context")

    name = call.name
    rows = context.rows
    if name == "COUNT" and call.star:
        return len(rows)

    values = []
    for row in rows:
        value = _eval(call.args[0], _RowContext(context.table, row))
        if value is not None:
            values.append(value)

    if name == "COUNT":
        return len(values)
    if not values:
        return None

    if name == "SUM":
        total = 0
        for value in values:
            if not _is_number(value):
                raise QueryError("SUM expects numbers")
            total += value
        return total

    if name == "AVG":
        total = 0
        for value in values:
            if not _is_number(value):
                raise QueryError("AVG expects numbers")
            total += value
        return total / len(values)

    if name in ("MIN", "MAX"):
        best = values[0]
        for value in values[1:]:
            comparison = _compare_values(value, best)
            if (name == "MIN" and comparison < 0) or (
                name == "MAX" and comparison > 0
            ):
                best = value
        return best

    raise QueryError("unknown aggregate: %s" % name)


def _eval(expr, context):
    if isinstance(expr, Literal):
        return expr.value

    if isinstance(expr, Column):
        if expr.index is None:
            raise QueryError("unresolved column: %s" % expr.name)
        return context.column(expr.index)

    if isinstance(expr, Unary):
        value = _eval(expr.operand, context)
        if expr.op == "NOT":
            return _negate(value)
        if expr.op == "-":
            if value is None:
                return None
            if not _is_number(value):
                raise QueryError("unary - expects a number")
            return -value
        raise QueryError("unknown unary operator: %s" % expr.op)

    if isinstance(expr, Binary):
        if expr.op in ("AND", "OR"):
            left = _eval(expr.left, context)
            right = _eval(expr.right, context)
            if expr.op == "AND":
                return _logical_and(left, right)
            return _logical_or(left, right)

        left = _eval(expr.left, context)
        right = _eval(expr.right, context)

        if expr.op in ("=", "!=", "<>", "<", "<=", ">", ">="):
            return _compare_op(left, right, expr.op)

        if expr.op == "||":
            if left is None or right is None:
                return None
            return _to_text(left) + _to_text(right)

        if expr.op in ("+", "-", "*", "/"):
            if left is None or right is None:
                return None
            if not _is_number(left) or not _is_number(right):
                raise QueryError(
                    "cannot apply %s to %s and %s"
                    % (expr.op, _type_name(left), _type_name(right))
                )
            if expr.op == "+":
                return left + right
            if expr.op == "-":
                return left - right
            if expr.op == "*":
                return left * right
            if right == 0:
                return None
            return left / right

        raise QueryError("unknown binary operator: %s" % expr.op)

    if isinstance(expr, IsNull):
        value = _eval(expr.operand, context)
        result = value is None
        return not result if expr.negated else result

    if isinstance(expr, InList):
        value = _eval(expr.operand, context)
        if value is None:
            result = None
        else:
            result = False
            saw_null = False
            for item in expr.items:
                item_value = _eval(item, context)
                if item_value is None:
                    saw_null = True
                    continue
                if _compare_op(value, item_value, "="):
                    result = True
                    break
            else:
                if saw_null:
                    result = None
        return _negate(result) if expr.negated else result

    if isinstance(expr, Between):
        value = _eval(expr.operand, context)
        low = _eval(expr.low, context)
        high = _eval(expr.high, context)
        result = _logical_and(
            _compare_op(low, value, "<="), _compare_op(value, high, "<=")
        )
        return _negate(result) if expr.negated else result

    if isinstance(expr, Like):
        value = _eval(expr.operand, context)
        pattern = _eval(expr.pattern, context)
        if value is None or pattern is None:
            result = None
        else:
            if not isinstance(value, str) or not isinstance(pattern, str):
                raise QueryError("LIKE expects strings")
            result = _like_regex(pattern).match(value) is not None
        return _negate(result) if expr.negated else result

    if isinstance(expr, FuncCall):
        if expr.name in _AGGREGATES:
            return _eval_aggregate(expr, context)
        return _eval_scalar(expr, context)

    raise QueryError("cannot evaluate expression")


# ---------------------------------------------------------------------------
# Query execution


@dataclass
class _Record:
    values: Tuple[Any, ...]
    order_values: Tuple[Any, ...]


def _make_groups(query, table, rows):
    if not query.group_by:
        representative = rows[0] if rows else None
        return [_GroupContext(table, list(rows), representative)]

    groups = []
    by_key = {}
    for row in rows:
        context = _RowContext(table, row)
        key = tuple(
            _value_key(_eval(expr, context)) for expr in query.group_by
        )
        group = by_key.get(key)
        if group is None:
            group = _GroupContext(table, [], row)
            by_key[key] = group
            groups.append(group)
        group.rows.append(row)
    return groups


def _make_record(query, prepared, context):
    values = tuple(_eval(item.expr, context) for item in prepared.items)
    order_values = []
    for kind, payload, _ in prepared.order:
        if kind == "output":
            order_values.append(values[payload])
        else:
            order_values.append(_eval(payload, context))
    return _Record(values, tuple(order_values))


def _sort_compare(left, right):
    if left is None and right is None:
        return 0
    if left is None:
        return -1
    if right is None:
        return 1
    return _compare_values(left, right)


def _order_comparator(prepared):
    def compare(left, right):
        for i, (_, _, descending) in enumerate(prepared.order):
            result = _sort_compare(
                left.order_values[i], right.order_values[i]
            )
            if descending:
                result = -result
            if result:
                return result
        return 0

    return compare


def _execute(query, table):
    prepared = _prepare(query, table)

    if query.where is None:
        rows = list(table.rows)
    else:
        rows = []
        for row in table.rows:
            value = _eval(query.where, _RowContext(table, row))
            if _condition_is_true(value, "WHERE"):
                rows.append(row)

    records = []
    if prepared.grouped:
        groups = _make_groups(query, table, rows)
        for group in groups:
            if query.having is not None:
                value = _eval(query.having, group)
                if not _condition_is_true(value, "HAVING"):
                    continue
            records.append(_make_record(query, prepared, group))
    else:
        for row in rows:
            context = _RowContext(table, row)
            if query.having is not None:
                value = _eval(query.having, context)
                if not _condition_is_true(value, "HAVING"):
                    continue
            records.append(_make_record(query, prepared, context))

    if query.distinct:
        seen = set()
        unique = []
        for record in records:
            key = tuple(_value_key(value) for value in record.values)
            if key not in seen:
                seen.add(key)
                unique.append(record)
        records = unique

    if prepared.order:
        records.sort(key=cmp_to_key(_order_comparator(prepared)))

    start = query.offset
    if query.limit is None:
        records = records[start:]
    else:
        records = records[start : start + query.limit]

    return prepared.columns, [record.values for record in records]


def run_query(sql, directory="."):
    query = parse(sql)
    table = _load_table(query.table_name, directory)
    return _execute(query, table)
